import QuantConnect as QC

class RsiStrategy(QC.Algorithm.Questions.Questions):
    def Initialize(self):
        self.SetStartDate(2024, 9, 1)
        self.SetEndDate(2024, 12, 31)
        self.SetCash(100_000)
        self.AddEquity("QQQ", QC.DataResolution.Hourly)
        self.rsi = QC.Indicators.RSI(self, 14, QC.Indicators.RsiType.Wilder)
        self.rsi_ready = False

    def OnData(self, data):
        if not self.rsi_ready:
            if self.rsi.IsReady:
                self.rsi_ready = True
            return

        rsi_value = self.rsi.Current.Value
        if rsi_value < 30:
            self.SetHoldings("QQQ", 1.0)
        elif rsi_value > 70:
            self.SetHoldings("QQQ", -1.0)
        else:
            self.SetHoldings("QQQ", 0.0)

        self.Log(f"RSI: {rsi_value:.2f}, Position: {self.Portfolio["QQQ"].TotalShares}")
        self.AddPlot("RSI", self.rsi)
